SELECT LAKEHOUSE_SCAN('{"table_root":"s3://warehouse/db/events","projection":["REGION","AMOUNT"],"filter":"(\"REGION\" = ''EU'')","limit":100,"emit_exa_types":["VARCHAR(2000000)","DECIMAL(18,2)"],"storage":{"connection":{"name":"LAKEHOUSE_CATALOG_CREDS","allow_http":true}},"df_target_partitions":4,"df_batch_size":8192,"df_threads_per_udf":2,"memory_pool_fraction":0.6,"instance_overhead_mb":200,"s3_max_connections":8}', files) EMITS ("REGION" VARCHAR(2000000), "AMOUNT" DECIMAL(18,2)) FROM (SELECT LAKEHOUSE_DISTRIBUTE_FILES(files) FROM (VALUES (0,'[["data/part-0.parquet",1000]]'),(1,'[["data/part-1.parquet",2000]]'),(2,'[["data/part-2.parquet",1500]]')) AS shards(shard_key, files) GROUP BY shard_key) LIMIT 100